#!/usr/bin/env bash
#
# fetch-fonts.sh regenerates the self-hosted web fonts used by present.
#
# It downloads WOFF2 subsets from the Fontsource packages on jsDelivr and
# writes cmd/present/static/fonts.css with the matching @font-face rules,
# including unicode-range so browsers only download the subsets they need.
#
# The generated files are committed to the repository, so this script is only
# needed to add a family, change weights, or bump font versions. A normal
# build does not run it.
#
# Usage:
#   tools/fetch-fonts.sh
#
# Requirements: curl, and network access to cdn.jsdelivr.net.

set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
static_dir="$root/cmd/present/static"
font_dir="$static_dir/fonts"
css_out="$static_dir/fonts.css"
cdn="https://cdn.jsdelivr.net/npm/@fontsource"

# "package|CSS family name|weights|styles"
families=(
  "inter|Inter|400 600 700|normal italic"
  "source-sans-3|Source Sans 3|400 600 700|normal italic"
  "ibm-plex-sans|IBM Plex Sans|400 600 700|normal italic"
  "source-serif-4|Source Serif 4|400 600 700|normal italic"
  "merriweather|Merriweather|400 700|normal italic"
  "eb-garamond|EB Garamond|400 600 700|normal italic"
  "jetbrains-mono|JetBrains Mono|400 700|normal"
  "source-code-pro|Source Code Pro|400 600 700|normal"
  "ibm-plex-mono|IBM Plex Mono|400 600 700|normal"
)

# Unicode ranges published by Google Fonts for each subset.
cat > "$css_out" <<'HEADER'
/*
 * fonts.css - self-hosted web fonts.
 *
 * Generated by tools/fetch-fonts.sh. Do not edit by hand.
 *
 * Each family is bundled as WOFF2 subsets with unicode-range, so a browser
 * downloads only the subset(s) needed for the text on the page. Override
 * --font-sans, --font-serif or --font-mono (see base.css) to use a different
 * family, or declare a custom @font-face in a theme stylesheet.
 */

HEADER

range_for() {
  case "$1" in
    latin)
      echo 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+2074,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD'
      ;;
    latin-ext)
      echo 'U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF'
      ;;
    greek)
      echo 'U+0370-0377,U+037A-037F,U+0384-038A,U+038C,U+038E-03A1,U+03A3-03FF'
      ;;
    greek-ext)
      echo 'U+1F00-1FFF'
      ;;
    cyrillic)
      echo 'U+0301,U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116'
      ;;
    cyrillic-ext)
      echo 'U+0460-052F,U+1C80-1C8A,U+20B4,U+2DE0-2DFF,U+A640-A69F,U+FE2E-FE2F'
      ;;
    vietnamese)
      echo 'U+0102-0103,U+0110-0111,U+0128-0129,U+0168-0169,U+01A0-01A1,U+01AF-01B0,U+0300-0301,U+0303-0304,U+0308-0309,U+0323,U+0329,U+1EA0-1EF9,U+20AB'
      ;;
  esac
}

subsets="latin latin-ext greek greek-ext cyrillic cyrillic-ext vietnamese"

download() {
  local url="$1" dest="$2"
  if [ -f "$dest" ]; then
    return 0
  fi
  if curl -fsS -o "$dest.tmp" "$url"; then
    mv "$dest.tmp" "$dest"
    return 0
  fi
  rm -f "$dest.tmp"
  return 1
}

count=0
for entry in "${families[@]}"; do
  IFS='|' read -r pkg family weights styles <<<"$entry"
  mkdir -p "$font_dir/$pkg"
  download "$cdn/$pkg/LICENSE" "$font_dir/$pkg/LICENSE" || true

  for weight in $weights; do
    for style in $styles; do
      for subset in $subsets; do
        file="$pkg-$subset-$weight-$style.woff2"
        dest="$font_dir/$pkg/$file"
        url="$cdn/$pkg/files/$file"
        if download "$url" "$dest"; then
          cat >> "$css_out" <<EOF
@font-face {
  font-family: '$family';
  font-style: $style;
  font-weight: $weight;
  font-display: swap;
  src: url('/static/fonts/$pkg/$file') format('woff2');
  unicode-range: $(range_for "$subset");
}

EOF
          count=$((count + 1))
        fi
      done
    done
  done
done

echo "wrote $count @font-face rules to $css_out"
